import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    try:
        t_str = next(iterator)
    except StopIteration:
        return

    t = int(t_str)
    results = []

    for _ in range(t):
        n = int(next(iterator))
        count = [0] * (n + 1)

        for _ in range(n):
            u = int(next(iterator))
            v = int(next(iterator))
            count[u] += 1
            count[v] += 1

        possible = True
        for i in range(1, n + 1):
            if count[i] > 2:
                possible = False
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
